## 错误处理与退出码

```rust
use anyhow::{Context, Result};
use std::process;

fn run() -> Result<()> {
    let config = std::fs::read_to_string("config.toml")
        .context("读取配置文件失败")?;

    println!("配置: {}", config);
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("{}: {:#}", "错误".red(), e);
        process::exit(1);
    }
}
```

